function renderProducts(filter='all'){
  const grid=document.getElementById('productsGrid');
  const list=filter==='all'?products:products.filter(p=>p.cat===filter);
  grid.innerHTML=list.map(p=>`
    <div class="product-card" id="card-${p.id}">
      ${p.badge?`<div class="promo-badge">${p.badge}</div>`:''}
      <div class="product-img-wrap">
        <img class="product-img" id="img-${p.id}" src="${p.img}" alt="${p.name}" loading="lazy">
        <div class="stock-badge"><div class="stock-dot"></div> In Stock · All Sizes</div>
      </div>
      <div class="product-info">
        <div class="product-tag">${p.tag}</div>
        <div class="product-name">${p.name}</div>
        <div class="size-row"><span class="size-chip">S</span><span class="size-chip">M</span><span class="size-chip">L</span><span class="size-chip">XL</span><span class="size-chip">XXL</span></div>
        <div class="product-desc">${p.desc}</div>
        <div class="product-footer">
          <div><span class="old-price">PKR ${p.old.toLocaleString()}</span><span class="cur-price">PKR ${p.price.toLocaleString()}</span></div>
          <button class="btn-order" onclick="openModal('${p.name}','${p.img}')">Order Now</button>
        </div>
      </div>
    </div>`).join('');
}

function filterProducts(cat,btn){
  document.querySelectorAll('.filter-btn').forEach(b=>b.classList.remove('active'));
  btn.classList.add('active');
  renderProducts(cat);
}

function openModal(name,imgSrc){
  document.getElementById('modalProduct').textContent=name;
  document.getElementById('modalImg').src=imgSrc;
  document.getElementById('modalOverlay').classList.add('active');
  document.body.style.overflow='hidden';
}

function closeModal(){
  document.getElementById('modalOverlay').classList.remove('active');
  document.body.style.overflow='';
}

function submitModalOrder(){
  const name=document.getElementById('modalName').value.trim();
  const phone=document.getElementById('modalPhone').value.trim();
  const size=document.getElementById('modalSize').value;
  const city=document.getElementById('modalCity').value.trim();
  const product=document.getElementById('modalProduct').textContent;
  if(!name||!phone||!city){alert('Please fill all fields!');return;}
  const msg=`🛍️ *New Order — WH William Henry*\n\n👤 Name: ${name}\n📱 Phone: ${phone}\n🏙️ City: ${city}\n\n👕 Style: ${product}\n📐 Size: ${size}\n\n💰 Price: PKR 1,099\n🚚 Delivery: PKR 250\n🧾 Total: PKR 1,349\n💳 Payment: COD\n\n✅ Please confirm my order!`;
  window.open(`https://wa.me/923353397964?text=${encodeURIComponent(msg)}`,'_blank');
  closeModal();showToast();
}

function submitOrder(){
  const name=document.getElementById('custName').value.trim();
  const phone=document.getElementById('custPhone').value.trim();
  const city=document.getElementById('custCity').value.trim();
  const address=document.getElementById('custAddress').value.trim();
  const product=document.getElementById('custProduct').value;
  const size=document.getElementById('custSize').value;
  const qty=document.getElementById('custQty').value;
  const payment=document.querySelector('input[name="payment"]:checked').value;
  if(!name||!phone||!city||!address||!product||!size){alert('Please fill all required fields!');return;}
  const msg=`🛍️ *New Order — WH William Henry*\n\n👤 Name: ${name}\n📱 Phone: ${phone}\n🏙️ City: ${city}\n🏠 Address: ${address}\n\n👕 Style: ${product}\n📐 Size: ${size}\n🔢 Qty: ${qty}\n\n💰 Price: PKR 1,099/piece\n🚚 Delivery: PKR 250\n💳 Payment: ${payment}\n\n✅ Please confirm my order!`;
  window.open(`https://wa.me/923353397964?text=${encodeURIComponent(msg)}`,'_blank');
  document.getElementById('orderForm').style.display='none';
  document.getElementById('successMsg').style.display='block';
  showToast();
}

function showToast(){
  const t=document.getElementById('toast');
  t.classList.add('show');
  setTimeout(()=>t.classList.remove('show'),3500);
}

function toggleNav(){
  document.getElementById('navLinks').classList.toggle('open');
}

// FAQ Section
const faqQuestions = document.querySelectorAll(".faq-question");
faqQuestions.forEach(question => {
  question.addEventListener("click", () => {
    const faqBox = question.parentElement;
    const answer = faqBox.querySelector(".faq-answer");
    faqBox.classList.toggle("active");
    if(faqBox.classList.contains("active")){
      answer.style.maxHeight = answer.scrollHeight + "px";
      question.querySelector("span").innerText = "-";
    } else {
      answer.style.maxHeight = "0px";
      question.querySelector("span").innerText = "+";
    }
  });
});

// Modal overlay close on background click
document.getElementById('modalOverlay').addEventListener('click',function(e){if(e.target===this)closeModal();});

// Scroll reveal animation
const obs=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting)e.target.classList.add('visible');}),{threshold:0.1});
document.querySelectorAll('.reveal').forEach(el=>obs.observe(el));

// Init
renderProducts();